// עבר QA пользователем 03.11.2026 («прошли»).
// Ожидаемо: длинное имя в шапке обрезается многоточием и заканчивается ДО кнопки даты/времени, тексты не накладываются,
// дата и окно молитвы читаются (Figma S-01 436:1292 — имя и дата в одной строке шапки с зазором).
// Факт 03.11 16:15 (iPhone 17, TestFlight 1.0.0 (20) + OTA 38b2d3b0, 2× перезапуск; .qa/session-2026-11-03.json round2,
// скрины .qa/screenshots/58ba6a-0311b-ios-01-home-longname.png, -02-journey-longname.png), точки iOS, y72 h36:
//   «בית»       — Button «מעבר לפרטים שלי» x166..378 («Tatiana Dombek Alexandr…»), Button «זמני התפילות של היום» x72..154
//   «המסע שלי»  — имя x185..378 («Tatiana Dombek Alexa…»), дата/время x72..174 («כ״ג חשון תשפ״ז», «מנחה 11:51 - 16:49»)
// Критерий: правый край кнопки даты + 8 pt ≤ левый край кнопки имени (RTL: имя справа, дата слева); обе в пределах экрана.
// Данные: меняет «שם מלא» вошедшего аккаунта на «Tatiana Dombek Alexandrovna Longname» и в finally возвращает исходное
// (прочитанное из поля; запасное — QA_GREETING_RESTORE_NAME, по умолчанию «QA reg 0311»). Временная правка профиля, не запись → не QA-AUTO-.
// Платформа: только iPhone (тикет iOS; Android не проверялся → skip). Кейс: .qa/tests/home/HM-10-header-long-name-no-overlap-date.md.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { $, $$, driver, expect } from '@wdio/globals';
import { byLabel, byTextContains, tapText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { goTab } from '../../helpers/nav.ts';
import { type Rect } from '../_lib/app-1310.ts';
import { skipWith } from '../_lib/app-0710.ts';
import { NAME_LONG, readProfileName, setProfileName, backToHome, stableRect } from '../_lib/app-0311.ts';

const QA_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..');
const SHOTS = path.join(QA_DIR, 'screenshots/app-regress/qa-0311');

const NAME_BTN = 'מעבר לפרטים שלי';
const DATE_BTN = 'זמני התפילות של היום';
const MIN_GAP = 8; // pt; 03.11: главная 12, «המסע שלי» 11

async function saveShot(file: string) {
  fs.mkdirSync(SHOTS, { recursive: true });
  await driver.saveScreenshot(path.join(SHOTS, file));
}

/** Первый ВИДИМЫЙ элемент с подписью (экраны вкладок могут оставаться в дереве). */
async function displayedByLabel(label: string): Promise<WebdriverIO.Element | undefined> {
  for (const el of await $$(`~${label}`)) {
    if (await el.isDisplayed().catch(() => false)) return el as unknown as WebdriverIO.Element;
  }
  return undefined;
}

/** Кнопка даты/времени: подпись «זמני התפילות של היום»; запасной вариант — кнопка с еврейским годом «תשפ…» в подписи. */
async function dateButton(): Promise<WebdriverIO.Element | undefined> {
  const byName = await displayedByLabel(DATE_BTN);
  if (byName) return byName;
  for (const el of await $$('-ios predicate string:type == "XCUIElementTypeButton" AND label CONTAINS "תשפ"')) {
    if (await el.isDisplayed().catch(() => false)) return el as unknown as WebdriverIO.Element;
  }
  return undefined;
}

async function openJourney() {
  await goTab('המסע שלי');
  await driver.waitUntil(async () => !!(await displayedByLabel(NAME_BTN)), { timeout: 20000, timeoutMsg: '«המסע שלי»: нет шапки с именем' });
  const w = await byTextContains('עלית דרגה');
  if (await w.waitForDisplayed({ timeout: 1500 }).then(() => true, () => false)) await tapText('סגירה');
}

/** Замер строки шапки и проверка: дата + 8 pt ≤ имя, обе на экране. */
async function checkHeader(screen: string, shot: string): Promise<{ name: Rect; date: Rect }> {
  const name = await stableRect(() => displayedByLabel(NAME_BTN), `${screen}: кнопка «${NAME_BTN}»`);
  const date = await stableRect(() => dateButton(), `${screen}: кнопка даты «${DATE_BTN}»`);
  const { width: W } = await driver.getWindowSize();
  await saveShot(shot);
  const gap = name.x - (date.x + date.width);
  console.log(`[Q-26] ${screen}: имя x${name.x}..${name.x + name.width} y${name.y} h${name.height}; дата x${date.x}..${date.x + date.width} y${date.y} h${date.height}; зазор ${gap}`);

  // Одна строка шапки (иначе горизонтальный зазор ничего не значит): вертикальные полосы пересекаются.
  expect(date.y < name.y + name.height && name.y < date.y + date.height).toBe(true);
  // Главное требование: длинное имя заканчивается до даты, с зазором.
  expect(date.x + date.width + MIN_GAP).toBeLessThanOrEqual(name.x);
  // Дата видна и не сжата в ноль; имя не уходит за правый край.
  expect(date.width).toBeGreaterThan(0);
  expect(date.x).toBeGreaterThanOrEqual(0);
  expect(name.x + name.width).toBeLessThanOrEqual(W);
  return { name, date };
}

describe('03.11 — шапка: длинное имя не налезает на дату (#58ba6a)', () => {
  afterEach(async () => { await toHome().catch(() => {}); });

  it('HM-10 Имя «Tatiana Dombek Alexandrovna Longname» в шапке «בית» и «המסע שלי» обрезается до кнопки «זמני התפילות של היום» (дата + 8 pt ≤ имя, одна строка); имя возвращается #58ba6a #47b60dea @iphone @data', async function () {
    if (driver.isAndroid) skipWith(this, '#58ba6a — тикет iOS, проверен на iPhone 17; Android не проверялся');

    const original = await readProfileName();
    try {
      await setProfileName(NAME_LONG);

      // 1. «בית» (03.11: имя x166..378, дата x72..154).
      await toHome();
      await (await byLabel('התחל תפילה')).waitForDisplayed({ timeout: 20000 });
      await checkHeader('בית', '58ba6a-q26-1-home-longname.png');

      // 2. «המסע שלי» (03.11: имя x185..378, дата/время x72..174).
      await openJourney();
      await checkHeader('המסע שלי', '58ba6a-q26-2-journey-longname.png');
    } finally {
      // Уборка: вернуть исходное имя (03.11 — «QA reg 0311») и убедиться, что оно в подписи кнопки имени на главной.
      await backToHome().catch(() => {});
      await setProfileName(original);
      await driver.waitUntil(async () => {
        const el = await displayedByLabel(NAME_BTN);
        if (!el) return false;
        const near = await el.$(`-ios predicate string:label CONTAINS "${original.replace(/"/g, '\\"')}"`).isExisting().catch(() => false);
        return near || (await $(`-ios predicate string:label CONTAINS "${original.replace(/"/g, '\\"')}"`).isDisplayed().catch(() => false));
      }, { timeout: 20000, interval: 500, timeoutMsg: `исходное имя «${original}» не вернулось на главную` });
    }
  });
});
